# rice-backup: restic backups of $HOME.
#   rice-backup init <repo>             set up (a local path, sftp:, rclone:, b2:, ...)
#   rice-backup now                     back up, then forget/prune old snapshots
#   rice-backup status                  the last snapshot, its age and the repo
#   rice-backup restore <path> [snap]   restore into ~/restore/<date>/, never in place
#
# Config lives in ~/.config/rice-backup: `repo` (the restic repository),
# `password` (mode 600, generated by init) and optionally `env` (KEY=VALUE lines
# exported to restic, e.g. B2_ACCOUNT_ID / B2_ACCOUNT_KEY). State (last
# success, last overdue warning) lives in ~/.local/state/rice-backup.
#
# `now` never fails for a reason that isn't a failure: not set up, or a local
# repository whose drive isn't plugged in, exit 0. When the last success is
# over 7 days old it warns (phone-alert and notify-send, once a day at most);
# a failed backup goes to the phone.
#
# Overrides (tests): RICE_BACKUP_DIR, RICE_BACKUP_STATE_DIR, RICE_BACKUP_HOME
# (what is backed up), RICE_BACKUP_RESTORE_DIR, RICE_BACKUP_NOW (epoch seconds).

cfg_dir=${RICE_BACKUP_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/rice-backup}
state_dir=${RICE_BACKUP_STATE_DIR:-${XDG_STATE_HOME:-$HOME/.local/state}/rice-backup}
src=${RICE_BACKUP_HOME:-$HOME}
restore_root=${RICE_BACKUP_RESTORE_DIR:-$HOME/restore}
now=${RICE_BACKUP_NOW:-$(date +%s)}

repo_file=$cfg_dir/repo
pw_file=$cfg_dir/password
env_file=$cfg_dir/env

day=86400
overdue_after=$((7 * day))

usage() {
  cat <<'EOF'
usage: rice-backup init <repo>            set up; <repo> is any restic repository:
                                           /run/media/$USER/<label>/restic, sftp:host:/path,
                                           b2:bucket:path, rclone:remote:path
       rice-backup now                    back up $HOME now (the daily timer runs this)
       rice-backup status                 the last snapshot, its age and the repo
       rice-backup restore <path> [snap]  restore <path> (default: latest) into ~/restore/<date>/
EOF
}

say() { echo "rice-backup: $*"; }
warn() { echo "rice-backup: $*" >&2; }

# "3 days ago", "1 day ago", "5 hours ago", "just now"
ago() {
  local s=$(($1))
  if [ "$s" -ge "$day" ]; then
    local d=$((s / day))
    [ "$d" = 1 ] && echo "1 day ago" || echo "$d days ago"
  elif [ "$s" -ge 3600 ]; then
    local h=$((s / 3600))
    [ "$h" = 1 ] && echo "1 hour ago" || echo "$h hours ago"
  elif [ "$s" -ge 60 ]; then
    echo "$((s / 60)) min ago"
  else
    echo "just now"
  fi
}

# Local repositories are plain paths (or local:/path); anything else with a
# backend prefix (sftp:, b2:, rclone:, s3:, rest:, ...) is remote.
local_path() {
  case $1 in
    local:*) echo "${1#local:}" ;;
    /*) echo "$1" ;;
    *) return 1 ;;
  esac
}

# A local repository is reachable when its `config` is there: an unplugged
# drive's mount point is gone, or is an empty folder on the root disk that
# restic must not write into.
repo_reachable() {
  local p
  p=$(local_path "$1") || return 0
  [ -f "$p/config" ]
}

load_config() {
  [ -s "$repo_file" ] || return 1
  repo=$(head -n 1 "$repo_file")
  [ -n "$repo" ] || return 1
  if [ -f "$env_file" ]; then
    set -a
    # shellcheck source=/dev/null
    . "$env_file"
    set +a
  fi
}

r() { restic -r "$repo" --password-file "$pw_file" "$@"; }

last_success() {
  local t
  t=$(cat "$state_dir/last-success" 2>/dev/null || true)
  [ -n "$t" ] || t=$(cat "$state_dir/since" 2>/dev/null || true)
  echo "${t:-}"
}

# Warn (phone and desktop) when the last success is over a week old, at most
# once a day. Neither may fail the run: the phone may be away.
check_overdue() {
  local last last_alert
  last=$(last_success)
  [ -n "$last" ] || return 0
  [ $((now - last)) -gt "$overdue_after" ] || return 0
  last_alert=$(cat "$state_dir/last-alert" 2>/dev/null || echo 0)
  [ $((now - last_alert)) -ge "$day" ] || return 0
  local msg
  if [ -f "$state_dir/last-success" ]; then
    msg="The last backup was $(ago $((now - last)))."
  else
    msg="No backup yet; it was set up $(ago $((now - last)))."
  fi
  msg="$msg Plug in the backup drive or run rice-backup now."
  warn "$msg"
  phone-alert "Backup overdue: $msg" >/dev/null 2>&1 || true
  notify-send -a rice-backup -i drive-harddisk "Backup overdue" "$msg" >/dev/null 2>&1 || true
  mkdir -p "$state_dir"
  echo "$now" > "$state_dir/last-alert"
}

failed() {
  warn "$1"
  phone-alert --critical "Backup failed: $1" >/dev/null 2>&1 || true
  notify-send -u critical -a rice-backup -i drive-harddisk "Backup failed" "$1" >/dev/null 2>&1 || true
}

write_excludes() {
  local f=$1
  {
    printf '%s\n' \
      "$src/.cache" \
      "$src/.local/share/Steam" \
      "$src/.steam" \
      "$src/.local/share/Trash" \
      "$src/.local/share/containers" \
      "$src/.local/share/libvirt/images" \
      "$src/.local/share/gnome-boxes/images" \
      "$src/VirtualBox VMs" \
      "$src/.npm/_cacache" \
      "$src/.cargo/registry" \
      "$src/go/pkg/mod" \
      "$src/Downloads/*.iso" \
      "$restore_root" \
      node_modules \
      .direnv \
      '*.qcow2' '*.vdi' '*.vmdk' '*.vhd' '*.vhdx'
    # A local repository inside $HOME must not back itself up.
    local p
    if p=$(local_path "$repo"); then echo "$p"; fi
    # nix build's result links (symlinks into the store), not folders that
    # happen to be called "result".
    find "$src" -xdev \
      \( -path "$src/.cache" -o -path "$src/.local/share/Steam" -o -name node_modules -o -name .direnv \) -prune \
      -o -type l \( -name result -o -name 'result-*' \) -lname '/nix/store/*' -print 2>/dev/null || true
  } > "$f"
}

cmd_init() {
  [ $# -eq 1 ] && [ -n "$1" ] || { usage >&2; exit 2; }
  repo=$1
  mkdir -p "$cfg_dir"
  chmod 700 "$cfg_dir"
  if [ ! -s "$pw_file" ]; then
    (umask 077 && head -c 33 /dev/urandom | base64 > "$pw_file")
    say "made a password in $pw_file"
    say "keep a copy somewhere off this machine (a password manager): without it the backups can't be read"
  fi
  chmod 600 "$pw_file"
  if [ -f "$env_file" ]; then
    set -a
    # shellcheck source=/dev/null
    . "$env_file"
    set +a
  fi
  if r cat config >/dev/null 2>&1; then
    say "$repo is already a repository this password opens; using it"
  elif ! r init; then
    warn "restic init failed for $repo (nothing saved)."
    warn "an existing repository needs its password in $pw_file; a cloud one may need its keys in $env_file"
    exit 1
  fi
  echo "$repo" > "$repo_file"
  mkdir -p "$state_dir"
  [ -f "$state_dir/since" ] || echo "$now" > "$state_dir/since"
  say "set up: $repo. The daily timer backs up from now on; rice-backup now runs one at once."
}

cmd_now() {
  if ! load_config; then
    say "not set up yet, nothing to do. Run: rice-backup init <repo>"
    exit 0
  fi
  mkdir -p "$state_dir"
  exec 9> "$state_dir/lock"
  if ! flock -n 9; then
    say "a backup is already running"
    exit 0
  fi
  if ! repo_reachable "$repo"; then
    say "$repo is not mounted (backup drive unplugged?), skipping"
    check_overdue
    exit 0
  fi

  local excludes rc=0
  excludes=$(mktemp)
  # shellcheck disable=SC2064
  trap "rm -f '$excludes'" EXIT
  write_excludes "$excludes"

  r backup "$src" --tag rice-backup --one-file-system --exclude-caches \
    --exclude-file "$excludes" || rc=$?
  # 3: a snapshot was made, but some files couldn't be read.
  if [ "$rc" != 0 ] && [ "$rc" != 3 ]; then
    failed "restic backup to $repo exited $rc (see journalctl --user -u rice-backup)"
    check_overdue
    exit 1
  fi
  [ "$rc" = 3 ] && warn "some files could not be read; the snapshot has the rest"
  echo "$now" > "$state_dir/last-success"

  if ! r forget --tag rice-backup --prune --keep-daily 7 --keep-weekly 4 --keep-monthly 6; then
    failed "the backup worked, but pruning old snapshots in $repo failed"
    exit 1
  fi
  say "done"
}

cmd_status() {
  if ! load_config; then
    say "not set up yet. Run: rice-backup init <repo>"
    exit 0
  fi
  echo "repo:          $repo"
  local last
  last=$(cat "$state_dir/last-success" 2>/dev/null || true)
  if [ -n "$last" ]; then
    echo "last success:  $(date -d "@$last" '+%Y-%m-%d %H:%M') ($(ago $((now - last))))"
  else
    echo "last success:  never"
  fi
  if ! repo_reachable "$repo"; then
    echo "snapshots:     (not mounted, plug in the backup drive to see them)"
    return 0
  fi
  local json id t
  if ! json=$(r snapshots --latest 1 --json); then
    warn "could not list snapshots in $repo"
    exit 1
  fi
  id=$(jq -r 'if length > 0 then .[-1].short_id else empty end' <<<"$json")
  t=$(jq -r 'if length > 0 then .[-1].time else empty end' <<<"$json")
  if [ -z "$id" ]; then
    echo "last snapshot: none yet"
    return 0
  fi
  local ts
  ts=$(date -d "$t" +%s)
  echo "last snapshot: $id, $(date -d "@$ts" '+%Y-%m-%d %H:%M') ($(ago $((now - ts))))"
}

cmd_restore() {
  [ $# -ge 1 ] && [ $# -le 2 ] && [ -n "$1" ] || { usage >&2; exit 2; }
  if ! load_config; then
    say "not set up yet. Run: rice-backup init <repo>"
    exit 0
  fi
  if ! repo_reachable "$repo"; then
    warn "$repo is not mounted; plug in the backup drive"
    exit 1
  fi
  local path snap target
  path=$(realpath -m -- "$1")
  snap=${2:-latest}
  target=$restore_root/$(date -d "@$now" +%F)
  mkdir -p "$target"
  r restore "$snap" --target "$target" --include "$path"
  say "restored into $target$path"
}

case ${1:-} in
  init) shift; cmd_init "$@" ;;
  now) cmd_now ;;
  status) cmd_status ;;
  restore) shift; cmd_restore "$@" ;;
  -h | --help | help) usage ;;
  *) usage >&2; exit 2 ;;
esac
